<template>
  <main class="storage-dashboard" dir="rtl">
    <header class="storage-heading">
      <div><span class="storage-eyebrow">مدیریت فضای سایت</span><h1>فضای ذخیره‌سازی</h1><p>مصرف فایل‌ها، ظرفیت باقی‌مانده و بسته‌های افزایش فضا را اینجا ببینید.</p></div>
      <button class="storage-refresh" type="button" @click="load" :disabled="loading"><span aria-hidden="true">↻</span>{{ loading ? 'در حال بررسی...' : 'به‌روزرسانی' }}</button>
    </header>
    <p v-if="error" class="storage-error" role="alert">{{ error }}</p>
    <template v-if="storage">
      <section class="storage-overview" :class="tone">
        <div class="storage-overview-top"><span class="storage-overview-label">وضعیت فضای فایل‌ها</span><span class="storage-state">{{ storage.percentage >= 100 ? 'ظرفیت تکمیل' : storage.percentage >= 90 ? 'وضعیت بحرانی' : storage.percentage >= 80 ? 'نیازمند توجه' : 'عادی' }}</span></div>
        <div class="storage-overview-numbers"><strong>{{ formatSize(storage.used_bytes) }}</strong><span>از {{ formatSize(storage.quota_bytes) }} ظرفیت کل</span></div>
        <div class="storage-progress" role="progressbar" :aria-valuenow="Math.min(100, Number(storage.percentage || 0))" aria-valuemin="0" aria-valuemax="100" aria-label="درصد فضای مصرف‌شده"><i :style="{ width: `${Math.min(100, Number(storage.percentage || 0))}%` }"></i></div>
        <div class="storage-overview-bottom"><span>{{ Number(storage.percentage || 0).toLocaleString('fa-IR') }}٪ مصرف شده</span><strong>{{ formatSize(storage.remaining_bytes) }} باقی‌مانده</strong></div>
        <p v-if="storage.percentage >= 80" class="storage-warning">{{ storage.percentage >= 100 ? 'ظرفیت فایل‌ها تکمیل شده و دسترسی به سامانه تا فعال شدن فضای بیشتر متوقف است.' : 'برای جلوگیری از توقف کار با سامانه، بهتر است فضای باقی‌مانده را بررسی کنید.' }}</p>
      </section>
      <div class="storage-metrics"><article><span>ظرفیت پایه</span><strong>{{ formatSize(storage.base_quota_bytes) }}</strong><small>فضای اولیهٔ سایت</small></article><article><span>فضای در دسترس</span><strong>{{ formatSize(storage.remaining_bytes) }}</strong><small>برای فایل‌های جدید</small></article><article><span>آخرین بررسی</span><strong class="storage-date">{{ formatDate(storage.scanned_at) }}</strong><small>شمارش فایل‌های سایت</small></article></div>
      <div class="storage-columns">
        <section class="storage-card"><header><h2>مصرف به تفکیک</h2><span>فایل‌های سایت</span></header><div v-for="(label, key) in labels" :key="key" class="storage-category"><div><span>{{ label }}</span><strong>{{ formatSize(storage.breakdown?.[key] || 0) }}</strong></div><i><b :style="{ width: `${categoryPercentage(storage.breakdown?.[key])}%` }"></b></i></div></section>
        <section class="storage-card storage-database"><header><h2>حجم دیتابیس</h2><span>محاسبه در لحظه</span></header><p>حجم دیتابیس تقریبی است و در سهمیهٔ فایل‌ها محاسبه نمی‌شود.</p><strong class="database-number">{{ databaseBytes === null ? 'هنوز محاسبه نشده' : formatSize(databaseBytes) }}</strong><button type="button" @click="loadDatabase" :disabled="databaseLoading">{{ databaseLoading ? 'در حال محاسبه...' : 'محاسبه حجم دیتابیس' }}</button><small v-if="databaseMeasuredAt">آخرین محاسبه: {{ formatDate(databaseMeasuredAt) }}</small></section>
      </div>
      <section class="storage-card storage-packages"><header><div><h2>افزایش فضا</h2><p>هزینهٔ بسته‌ها ماهانه است و فضا پس از بررسی پرداخت و تأیید مدیریت فعال می‌شود.</p></div></header><p v-if="!packages.length" class="storage-empty">هنوز بسته‌ای برای خرید تعریف نشده است.</p><div v-else class="package-grid"><article v-for="item in packages" :key="item.id"><span class="package-size">{{ Number(item.size_gb).toLocaleString('fa-IR') }} گیگابایت</span><h3>{{ item.name }}</h3><p><strong>{{ Number(item.monthly_price).toLocaleString('fa-IR') }}</strong> تومان / ماه</p><button type="button" :disabled="ordering" @click="order(item)">درخواست خرید <span aria-hidden="true">←</span></button></article></div><p v-if="message" class="storage-message" role="status">{{ message }}</p></section>
      <section v-if="orders.length" class="storage-card storage-orders"><header><h2>درخواست‌ها و بسته‌های من</h2></header><div v-for="item in orders" :key="item.id" class="storage-order"><div><strong>{{ item.package_name }}</strong><small>{{ formatSize(item.size_bytes) }} فضای اضافه</small></div><div><span :class="['order-status', item.status]">{{ orderStatus(item) }}</span><small v-if="item.expires_at">تا {{ formatDate(item.expires_at) }}</small></div></div></section>
    </template>
    <p v-else-if="loading" class="storage-loading">در حال دریافت وضعیت فضای ذخیره‌سازی...</p>
  </main>
</template>

<script setup>
import { onMounted, ref } from 'vue';
import axios from 'axios';
const storage = ref(null), packages = ref([]), orders = ref([]), databaseBytes = ref(null), databaseMeasuredAt = ref(null);
const loading = ref(false), databaseLoading = ref(false), ordering = ref(false), error = ref(''), message = ref('');
const labels = { patient_photos: 'تصاویر پرونده‌ها', patient_videos: 'ویدیوهای پرونده‌ها', patient_profiles: 'تصاویر پروفایل بیماران', staff_and_users: 'تصاویر کاربران و کارکنان', audio_and_notes: 'صوت و پیوست یادداشت‌ها', other: 'سایر فایل‌ها' };
const tone = ref('green');
function formatSize(bytes) { const value = Number(bytes || 0); return value >= 1073741824 ? `${(value / 1073741824).toLocaleString('fa-IR', { maximumFractionDigits: 2 })} گیگابایت` : `${(value / 1048576).toLocaleString('fa-IR', { maximumFractionDigits: 1 })} مگابایت`; }
function formatDate(value) { return value ? new Date(value).toLocaleString('fa-IR') : 'ثبت نشده'; }
function categoryPercentage(bytes) { return storage.value?.used_bytes ? Math.min(100, Number(bytes || 0) / storage.value.used_bytes * 100) : 0; }
function orderStatus(item) { return item.status === 'pending' ? 'در انتظار تأیید' : item.status === 'rejected' ? 'رد شده' : new Date(item.expires_at) > new Date() ? 'فعال' : 'منقضی شده'; }
async function load() { loading.value = true; error.value = ''; try { const { data } = await axios.get('/api/storage'); storage.value = data.storage; packages.value = data.packages || []; orders.value = data.orders || []; tone.value = data.storage.percentage >= 100 ? 'full' : data.storage.percentage >= 90 ? 'critical' : data.storage.percentage >= 80 ? 'warning' : 'green'; } catch (e) { error.value = e.response?.data?.message || 'دریافت اطلاعات فضا انجام نشد.'; } finally { loading.value = false; } }
async function loadDatabase() { databaseLoading.value = true; try { const { data } = await axios.get('/api/storage/database'); databaseBytes.value = data.database_bytes; databaseMeasuredAt.value = data.measured_at; } catch (e) { error.value = e.response?.data?.message || 'محاسبه حجم دیتابیس انجام نشد.'; } finally { databaseLoading.value = false; } }
async function order(item) { if (!confirm(`درخواست بسته ${item.name} با هزینه ماهانه ${Number(item.monthly_price).toLocaleString('fa-IR')} تومان ثبت شود؟`)) return; ordering.value = true; error.value = ''; try { const { data } = await axios.post('/api/storage/orders', { package_id: item.id }); message.value = data.message; await load(); } catch (e) { error.value = e.response?.data?.message || 'ثبت درخواست انجام نشد.'; } finally { ordering.value = false; } }
onMounted(load);
</script>

<style scoped>
.storage-dashboard{max-width:1100px;margin:0 auto;padding:8px 0 28px;color:#173237;display:grid;gap:18px;font-family:inherit}
.storage-heading,.storage-card>header{display:flex;align-items:center;justify-content:space-between;gap:16px}
.storage-eyebrow{color:#138575;font-size:11px;font-weight:900;letter-spacing:.02em}.storage-heading h1{margin:5px 0;font-size:26px;line-height:1.4}.storage-heading p,.storage-card p{margin:4px 0;color:#72828a;font-size:12px;line-height:1.9}
.storage-dashboard button{border:0;border-radius:10px;padding:10px 16px;background:#087e72;color:#fff;font:inherit;font-size:11px;font-weight:800;cursor:pointer;transition:background .2s,transform .2s}.storage-dashboard button:hover:not(:disabled){background:#096f64;transform:translateY(-1px)}.storage-dashboard button:disabled{opacity:.55;cursor:default}.storage-refresh{display:flex;align-items:center;gap:6px;white-space:nowrap}.storage-refresh span{font-size:20px;line-height:12px}
.storage-overview{padding:25px 28px;border:1px solid #cceae3;border-radius:21px;background:linear-gradient(120deg,#e9f9f4 0%,#f9fdfc 70%);box-shadow:0 12px 30px #0b5e4820}.storage-overview-top,.storage-overview-numbers,.storage-overview-bottom{display:flex;align-items:center;justify-content:space-between;gap:16px}.storage-overview-label{font-size:12px;font-weight:850;color:#3b736b}.storage-state{padding:5px 10px;border-radius:100px;background:#d6f2e8;color:#087e72;font-size:10px;font-weight:850}.storage-overview-numbers{justify-content:flex-start;align-items:baseline;margin-top:18px}.storage-overview-numbers strong{font-size:37px;line-height:1.4;letter-spacing:-.025em}.storage-overview-numbers span,.storage-overview-bottom{font-size:12px;color:#53716e}.storage-overview-bottom strong{color:#156f62}.storage-progress{height:11px;margin:17px 0 11px;border-radius:20px;background:#d7eae5;overflow:hidden}.storage-progress i{display:block;height:100%;border-radius:20px;background:#11a587;transition:width .4s}.storage-overview.orange{border-color:#f5dfa8;background:linear-gradient(120deg,#fff6de,#fffdf8)}.storage-overview.orange .storage-progress i,.storage-overview.yellow .storage-progress i{background:#e3a526}.storage-overview.orange .storage-state,.storage-overview.yellow .storage-state{background:#fef0c7;color:#996009}.storage-overview.red{border-color:#f7caca;background:linear-gradient(120deg,#fff0f0,#fffafa)}.storage-overview.red .storage-progress i{background:#de4949}.storage-overview.red .storage-state{background:#fee2e2;color:#b42323}.storage-warning{margin:16px 0 0!important;padding:10px 12px;border-radius:9px;background:#ffffffa8;color:#974c27!important;font-weight:700}
.storage-overview.warning{border-color:#f5dfa8;background:linear-gradient(120deg,#fff6de,#fffdf8)}.storage-overview.warning .storage-progress i{background:#e3a526}.storage-overview.warning .storage-state{background:#fef0c7;color:#996009}
.storage-overview.critical{border-color:#fecdd3;background:linear-gradient(120deg,#fff1f2,#fffafa)}.storage-overview.critical .storage-progress i{background:#e11d48}.storage-overview.critical .storage-state{background:#ffe4e6;color:#9f1239}.storage-overview.critical .storage-warning{color:#9f1239!important}
.storage-overview.full{border-color:#7f1d1d;background:linear-gradient(120deg,#991b1b,#7f1d1d);color:#fff;box-shadow:0 14px 34px #7f1d1d42}.storage-overview.full .storage-overview-label,.storage-overview.full .storage-overview-numbers span,.storage-overview.full .storage-overview-bottom,.storage-overview.full .storage-overview-bottom strong{color:#fee2e2}.storage-overview.full .storage-progress{background:#ffffff38}.storage-overview.full .storage-progress i{background:#fff}.storage-overview.full .storage-state{background:#fff;color:#991b1b}.storage-overview.full .storage-warning{background:#ffffff1f;color:#fff!important}
.storage-metrics{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}.storage-metrics article{display:grid;gap:7px;padding:17px 20px;border:1px solid #e0ebe9;border-radius:15px;background:#fff}.storage-metrics span,.storage-metrics small{font-size:11px;color:#73858b}.storage-metrics strong{font-size:20px;color:#183b3b}.storage-metrics .storage-date{font-size:14px;line-height:1.6}
.storage-columns{display:grid;grid-template-columns:minmax(0,1.4fr) minmax(0,.9fr);gap:16px;align-items:start}.storage-card{min-width:0;padding:21px 23px;border:1px solid #e0ebe9;border-radius:17px;background:#fff;box-shadow:0 7px 25px #17483a0a}.storage-card h2{margin:0;font-size:16px}.storage-card>header{margin-bottom:18px}.storage-card>header>span{font-size:10px;color:#8a9a9e}.storage-category{padding:9px 0}.storage-category>div{display:flex;justify-content:space-between;gap:12px;font-size:11px;color:#61787a}.storage-category strong{color:#284e4f}.storage-category i{display:block;height:5px;margin-top:8px;border-radius:10px;background:#eef4f2;overflow:hidden}.storage-category b{display:block;height:100%;border-radius:10px;background:#3fb89e}.storage-database{display:flex;flex-direction:column;align-items:flex-start;min-height:238px}.storage-database>header{align-self:stretch}.storage-database .database-number{margin:22px 0 15px;font-size:20px}.storage-database small{margin-top:12px;color:#85979a;font-size:10px}
.storage-packages>header{margin-bottom:14px}.storage-empty,.storage-loading{padding:20px;border-radius:10px;background:#f6faf9;color:#758987;font-size:12px}.package-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(205px,1fr));gap:12px}.package-grid article{display:flex;flex-direction:column;align-items:flex-start;padding:18px;border:1px solid #dcebe8;border-radius:14px;background:#f9fcfb}.package-size{padding:6px 9px;border-radius:8px;background:#e3f6f0;color:#087e72;font-size:11px;font-weight:850}.package-grid h3{margin:15px 0 4px;font-size:15px}.package-grid p{margin:0 0 16px}.package-grid p strong{color:#244747;font-size:16px}.package-grid button{margin-top:auto}.storage-message{padding:10px 12px;border-radius:9px;background:#e9f8f2;color:#107b62!important}
.storage-order{display:flex;align-items:center;justify-content:space-between;gap:16px;padding:13px 0;border-top:1px solid #edf2f1}.storage-order>div{display:grid;gap:5px}.storage-order>div:last-child{text-align:left}.storage-order strong{font-size:12px}.storage-order small{color:#829294;font-size:10px}.order-status{color:#087e72;font-size:11px;font-weight:850}.order-status.pending{color:#a16207}.order-status.rejected{color:#b42323}.storage-error{padding:11px 13px;border-radius:10px;background:#fff1e6;color:#9a3412;font-size:12px}
@media(max-width:760px){.storage-columns{grid-template-columns:1fr}.storage-heading{align-items:flex-start}.storage-metrics{grid-template-columns:repeat(2,minmax(0,1fr))}.storage-metrics article:last-child{grid-column:1/-1}}@media(max-width:560px){.storage-dashboard{gap:13px}.storage-heading{flex-wrap:wrap}.storage-heading h1{font-size:22px}.storage-overview{padding:20px}.storage-overview-numbers{display:grid;gap:0}.storage-overview-numbers strong{font-size:28px}.storage-metrics{grid-template-columns:1fr}.storage-metrics article:last-child{grid-column:auto}.storage-card{padding:18px}.storage-order{align-items:flex-start}}
</style>
